# -*- coding: utf-8 -*-
G=[]
def g(slug,tit,eq,desc,secs): G.append((slug,tit,eq,desc,secs))
g('altura-de-el-salvador-y-cocinas-a-gas-por-que-sale-llama-amarilla','Altura de El Salvador y cocinas a gas: por qué sale la llama amarilla','cocinas','El Salvador está a unos 2.800 m de altitud. Por qué eso afecta la llama de las cocinas y hornos a gas y cuándo pedir un ajuste de aire.',
 [('Qué cambia con la altura','Cuanto más alto, menos oxígeno tiene el aire. Un quemador necesita mezclar gas con aire en la proporción correcta; con menos oxígeno, la llama puede salir más amarilla, más larga o más débil si la mezcla no está ajustada.'),
  ('Cómo reconocer una llama sana','Una llama bien ajustada es azul, firme y de altura pareja alrededor del quemador. Una llama amarilla o naranja que ensucia las ollas de hollín indica mezcla descompensada o quemador sucio.'),
  ('Qué puedes revisar tú','<ul><li>Limpia el quemador y revisa que los orificios no estén tapados.</li><li>Verifica que las tapas del quemador estén bien asentadas.</li><li>Comprueba si pasa en todas las hornillas o solo en una.</li></ul>'),
  ('Cuándo pedir un técnico','Si la llama sigue amarilla después de limpiar, o si cambiaste de cilindro a gas centralizado, un técnico debe ajustar el aire y la presión. No manipules el gas sin experiencia.')])
g('voltaje-en-el-salvador-120-v-240-v-y-electrodomesticos-samsung','Voltaje en El Salvador: 120 V, 240 V y tus electrodomésticos Samsung','refrigeradoras','Qué voltaje usa cada electrodoméstico en casa en El Salvador, por qué importa el breaker y cómo evitar daños por conexiones incorrectas.',
 [('Dos tipos de toma','En los hogares de El Salvador la mayoría de tomacorrientes entrega unos 120 V. Equipos de mayor consumo, como algunas secadoras eléctricas, usan 240 V y necesitan toma y breaker propios.'),
  ('Cómo saberlo','La etiqueta del equipo indica el voltaje y la potencia. Si dice 240 V, no lo conectes a una toma de 120 V ni uses adaptadores caseros.'),
  ('Por qué importa el breaker','Un breaker muy pequeño se dispara y uno muy grande no protege el cable. Si el equipo hace saltar el breaker repetidamente, no lo subas: pide una revisión eléctrica.'),
  ('Protección','Usa un tomacorriente propio para la refrigeradora, y un protector de voltaje con retardo si tu zona tiene bajones o cortes.')])
g('como-encontrar-el-modelo-y-la-etiqueta-de-tu-electrodomestico-samsung','Cómo encontrar el modelo y la etiqueta de tu electrodoméstico Samsung','refrigeradoras','Dónde suele estar la etiqueta con el modelo y el número de serie en refrigeradoras, neveras, lavadoras y secadoras, y por qué es tan útil al pedir servicio.',
 [('Para qué sirve el modelo','Con el modelo se identifican las piezas, los códigos de error y los procedimientos de reparación. Sin él, el diagnóstico inicial por WhatsApp es mucho menos preciso.'),
  ('Dónde suele estar','<ul><li><b>Refrigeradora:</b> en el interior, en el costado o el techo del compartimento.</li><li><b>Lavadora:</b> atrás, o en el borde de la tapa o de la puerta.</li><li><b>Secadora:</b> dentro del marco de la puerta o atrás.</li></ul>'),
  ('Cómo enviarla','Toma una foto nítida de la etiqueta con buena luz y envíala por WhatsApp junto con una descripción de la falla.'),
  ('Si no la encuentras','Envía una foto del equipo completo y una del panel de control; con eso se puede orientar el diagnóstico.')])
g('como-proteger-tus-electrodomesticos-de-bajones-y-picos-de-voltaje','Cómo proteger tus electrodomésticos de bajones y picos de voltaje','refrigeradoras','Los bajones, cortes y picos de voltaje dañan compresores y tarjetas. Qué protector usar y qué hacer cuando vuelve la luz.',
 [('Qué daña la electricidad inestable','Los picos al volver la luz y los bajones prolongados castigan compresores, motores y tarjetas electrónicas. Las lavadoras y refrigeradoras modernas tienen más electrónica y son más sensibles.'),
  ('Qué protector conviene','Para refrigeradoras, un protector con retardo de reconexión evita que el compresor arranque de golpe. Para lavadoras y otros equipos con tarjeta, un protector contra picos.'),
  ('Después de un corte','Espera unos minutos antes de volver a encender; evita apagar y prender el compresor varias veces seguidas.'),
  ('Si el equipo no vuelve','Si después de un corte no enciende, no lo fuerces. Desconéctalo y escríbenos con el modelo.')])
g('que-hacer-si-huele-a-gas-en-casa','Qué hacer si huele a gas en casa: pasos de seguridad','cocinas','Olor a gas en la cocina: pasos inmediatos de seguridad, qué evitar y cuándo pedir un técnico y a emergencias.',
 [('Primero, seguridad','Cierra la llave del cilindro o del gas centralizado, abre puertas y ventanas para ventilar y sal del lugar si el olor es fuerte.'),
  ('Qué no hacer','No enciendas fósforos, luces ni interruptores, no uses el celular dentro del lugar con olor intenso, ni enciendas la cocina o el calentador para probar.'),
  ('Después de ventilar','Revisa si la perilla quedó abierta. Si no es eso, no vuelvas a usar la cocina: necesita revisión de manguera, conexiones y válvulas.'),
  ('Cuándo pedir un técnico','Si el olor es fuerte o no encuentras el origen, llama a emergencias (911). Para revisar el electrodoméstico, escríbenos.')])
g('instalar-una-secadora-en-un-apartamento-de-el-salvador-ducto-y-ventilacion','Instalar una secadora en un apartamento de El Salvador: ducto y ventilación','secadoras','Qué necesita una secadora en un apartamento: ducto de salida, ventilación, espacio y voltaje. Errores comunes y cómo evitarlos.',
 [('El ducto es clave','La secadora expulsa aire caliente y húmedo que debe salir al exterior. Un ducto corto y recto seca más rápido; uno largo, con curvas o aplastado hace que el secado tarde y la secadora se sobrecaliente.'),
  ('Espacio y ventilación','Deja separación con la pared para el ducto y para que el equipo respire. No la encierres en un clóset sin ventilación.'),
  ('Energía','Confirma que sea eléctrica (a menudo 240 V con breaker propio) y que la instalación esté preparada antes de comprar.'),
  ('Revisión periódica','Limpia el filtro en cada ciclo y el ducto al menos una vez al año.')])
g('cocina-a-gas-cilindro-o-gas-centralizado-que-cambia','Cocina a gas: cilindro o gas centralizado, qué cambia','cocinas','Diferencias de usar cilindro o gas centralizado en una cocina Samsung y por qué conviene revisar el ajuste al cambiar de uno a otro.',
 [('Dos formas de suministro','En El Salvador hay hogares con cilindro de gas y edificios con gas centralizado. La presión y las conexiones pueden ser distintas.'),
  ('Qué puede cambiar','La llama, la potencia del quemador y la regulación pueden cambiar. Un cambio de suministro puede requerir ajuste de aire e inyectores.'),
  ('Revisión de manguera','Revisa la manguera y los reguladores según su fecha de vencimiento y estado; cámbialos si están agrietados o vencidos.'),
  ('Qué hacer al mudarte','Pide una revisión de la cocina y del horno antes de usarlos en la nueva vivienda.')])
g('cuanto-cuesta-reparar-un-electrodomestico-samsung-en-el-salvador','Cuánto cuesta reparar un electrodoméstico Samsung en El Salvador','refrigeradoras','De qué depende el costo de reparar una refrigeradora, lavadora o secadora Samsung en El Salvador, y cómo evitar sorpresas.',
 [('De qué depende','Del tipo de equipo, la falla, la pieza que se cambie, su disponibilidad y el tiempo de trabajo. Por eso no hay un precio único.'),
  ('Qué debe incluir una cotización clara','Diagnóstico, costo de la pieza, mano de obra y, si aplica, costo de la visita. Pídelo antes de aceptar.'),
  ('Cuándo conviene reparar','Cuando la falla es de una pieza accesible y el equipo estaba funcionando bien. Si la reparación se acerca al costo de un equipo nuevo, conviene pensarlo.'),
  ('Cómo pedirlo','Escríbenos por WhatsApp con el modelo y la falla; te orientamos y te confirmamos el costo de la visita antes de ir.')])
g('checklist-anual-de-mantenimiento-de-electrodomesticos-del-hogar','Checklist anual de mantenimiento de los electrodomésticos del hogar','lavadoras','Una lista simple para revisar cada año refrigeradora, lavadora y secadora, y evitar reparaciones costosas.',
 [('Refrigeradora y congelador','Limpiar condensador y rejillas, revisar empaques, desagüe y filtro de agua.'),
  ('Lavadora y secadora','Limpiar tina, filtros y ducto; revisar mangueras y nivelación.'),
  ('Cuándo pedir ayuda','Si notas ruidos nuevos, olores, goteos o menor rendimiento, no esperes al año: pide una revisión.')])
g('como-pedir-servicio-tecnico-por-whatsapp-que-enviar','Cómo pedir servicio técnico por WhatsApp: qué enviar para un mejor diagnóstico','refrigeradoras','Qué datos, fotos y videos enviar por WhatsApp para que el técnico pueda orientarte rápido y coordinar la visita.',
 [('Los datos básicos','Tipo de equipo, marca y modelo, tu municipio o colonia y qué falla presenta.'),
  ('Fotos y video','Una foto de la etiqueta, una del equipo y, si es posible, un video corto del problema (ruido, código de error, fuga).'),
  ('Qué pasó antes','Cuenta si hubo corte de luz, golpe, cambio de lugar o si la falla es nueva o intermitente.'),
  ('Qué esperar','Te orientamos con lo que enviaste y coordinamos la visita. El diagnóstico definitivo se hace en el equipo.')])
g('garantia-de-fabrica-samsung-que-hacer-antes-de-reparar','Garantía de fábrica Samsung: qué hacer antes de reparar','refrigeradoras','Si tu electrodoméstico Samsung está en garantía, qué conviene revisar y hacer antes de pedir una reparación en El Salvador.',
 [('Si está en garantía','Revisa tu factura y las condiciones de la garantía. Mientras esté vigente, lo prudente es consultar primero con el fabricante o el punto de venta.'),
  ('Si ya venció','Un técnico a domicilio puede diagnosticar el equipo y repararlo si conviene.'),
  ('Cómo decidir','Compara qué incluye cada servicio, el costo de la visita, la garantía de la reparación y los tiempos.'),
  ('Cómo te ayudamos','Escríbenos por WhatsApp con el modelo y la falla: te orientamos y, si corresponde, coordinamos la visita y te damos el costo antes de reparar.')])
g('refrigeradora-nueva-samsung-que-hacer-los-primeros-dias','Refrigeradora nueva: qué hacer los primeros días','refrigeradoras','Cómo ubicar, nivelar y encender una refrigeradora nueva y qué es normal los primeros días.',
 [('Ubicación y nivelación','Colócala lejos de fuentes de calor, con espacio para ventilación y nivelada sobre sus patas.'),
  ('Antes de encender','Sigue las indicaciones del manual sobre el tiempo de reposo si fue transportada acostada y limpia el interior.'),
  ('Primeros días','Es normal que tarde en llegar a la temperatura. Evita llenarla de golpe con comida caliente.'),
  ('Cuándo preocuparse','Si después de un día no enfría, hace ruido fuerte o gotea, escríbenos.')])
g('lavadora-que-no-llena-de-agua-por-baja-presion-en-el-salvador','Lavadora que no llena de agua: baja presión y otras causas','lavadoras','Si tu lavadora Samsung tarda en llenar o no llena de agua, revisa la llave, las mallas de la manguera y la presión del agua.',
 [('Lo básico','Llave abierta, manguera sin dobleces y malla de entrada limpia.'),
  ('Presión del agua','En algunos edificios o sectores la presión baja en ciertos horarios; la lavadora puede demorar o marcar error.'),
  ('Válvula de entrada','Si la presión es buena y no llena, la válvula o el sensor de nivel pueden estar dañados.'),
  ('Cuándo pedir un técnico','Si ya revisaste lo anterior, pide un diagnóstico con el modelo.')])
g('como-descongelar-una-refrigeradora-samsung-sin-danarla','Cómo descongelar una refrigeradora o congelador sin dañarlo','refrigeradoras','Pasos seguros para descongelar y limpiar sin perforar el evaporador ni dañar plásticos.',
 [('Desconecta y vacía','Desconecta el equipo, pasa los alimentos a una hielera y abre las puertas.'),
  ('Deja que se derrita solo','Pon toallas y un recipiente. No uses objetos filosos ni secador de pelo.'),
  ('Limpia y seca','Limpia con agua tibia y bicarbonato, seca y revisa el empaque.'),
  ('Si la escarcha vuelve pronto','Puede haber un problema de descongelación o de sellado: pide una revisión.')])
g('como-limpiar-una-cocina-a-gas-sin-danar-los-quemadores','Cómo limpiar una cocina a gas sin dañar los quemadores','cocinas','Limpieza semanal de quemadores, tapas y bujías, y qué evitar para no tapar los orificios del gas.',
 [('Con la cocina fría y el gas cerrado','Cierra la llave y espera a que se enfríe todo.'),
  ('Quemadores y tapas','Remójalos en agua tibia con jabón y límpialos con cepillo suave; destapa los orificios con un cepillo, sin agrandarlos.'),
  ('Bujías','Límpialas con un paño casi seco; la humedad hace que el chispero haga clic sin parar.'),
  ('Secado','Seca todo bien antes de volver a armar y encender.')])
g('como-usar-bien-el-horno-evitar-fallas-y-malos-resultados','Cómo usar bien el horno para evitar fallas y malos resultados','hornos','Precalentar, no tapar el fondo, no abusar de la limpieza y otros hábitos que alargan la vida del horno.',
 [('Precalienta y espera','Deja que llegue a la temperatura antes de meter la comida; abrir la puerta con frecuencia baja la temperatura.'),
  ('No tapes el fondo','El papel aluminio en el fondo bloquea el calor y daña la resistencia o el quemador.'),
  ('Limpieza','Limpia derrames cuando el horno esté frío y no uses productos corrosivos.'),
  ('Si cocina desigual','Revisa que la puerta selle y pide revisión del sensor y el termostato.')])
g('ruidos-en-la-lavadora-que-significan-y-cuando-pedir-al-tecnico','Ruidos en la lavadora: qué significan y cuándo pedir al técnico','lavadoras','Golpes, chirridos, zumbidos y rechinidos: cómo distinguir un ruido normal de una falla en la lavadora.',
 [('Ruidos normales','Agua entrando, desagüe y un zumbido suave del motor.'),
  ('Golpes al centrifugar','Carga desbalanceada o patas sin nivelar; si pasa con poca ropa, amortiguadores.'),
  ('Chirridos o rechinidos','Rodamientos o correa desgastados; no esperes a que se dañe la tina.'),
  ('Cuándo pedir un técnico','Si el ruido es nuevo, fuerte o constante, pide una revisión.')])
g('cuanto-dura-un-electrodomestico-y-cuando-conviene-reemplazarlo','Cuánto dura un electrodoméstico y cuándo conviene reemplazarlo','refrigeradoras','Vida útil aproximada de refrigeradoras, lavadoras y secadoras, y señales de que ya no conviene repararlos.',
 [('Depende del uso y el cuidado','La vida útil varía por modelo, uso, instalación y mantenimiento; no hay una cifra exacta para todos.'),
  ('Señales de desgaste','Reparaciones repetidas, ruidos fuertes, consumo alto, óxido o piezas que ya no se consiguen.'),
  ('Regla práctica','Si la reparación se acerca al costo de uno nuevo y el equipo es muy viejo, evalúa reemplazarlo.'),
  ('Cómo decidir','Pide un diagnóstico: te decimos con honestidad si conviene reparar o no.')])
g('como-elegir-un-tecnico-de-electrodomesticos-en-el-salvador','Cómo elegir un técnico de electrodomésticos en El Salvador','refrigeradoras','Preguntas que conviene hacer antes de contratar un técnico: diagnóstico, costo, garantía de la reparación y repuestos.',
 [('Pide diagnóstico y costo antes','Un buen técnico explica la falla y el costo antes de empezar.'),
  ('Pregunta por la garantía de la reparación','Qué cubre y por cuánto tiempo; pídelo por escrito o por WhatsApp.'),
  ('Cuidado con las piezas cambiadas al azar','Pregunta cómo confirmó la falla.'),
  ('Referencias','Busca opiniones reales y comprueba que se identifique y llegue a la hora acordada.')])
